/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseURI } from './parser.js'
import { normalizeURI } from './normalizer.js'
import { resolveURI } from './resolver.js'
import { readStdin } from './stdin.js'

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = args[0]

  try {
    const input = await readStdin()
    const lines = input.split('\n')

    // Drop the empty tail a trailing newline leaves
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    if (mode === 'normalize') {
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        const uri = parseURI(line, i + 1)
        const normalized = normalizeURI(uri)
        process.stdout.write(normalized + '\n')
      }
    } else { // resolve
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        const spaceIndex = line.indexOf(' ')

        if (spaceIndex === -1) {
          process.stderr.write(`error: line ${i + 1}: expected a base and a reference\n`)
          process.exit(2)
        }

        const baseStr = line.substring(0, spaceIndex)
        const refStr = line.substring(spaceIndex + 1)

        const base = parseURI(baseStr, i + 1)

        if (!base.scheme) {
          process.stderr.write(`error: line ${i + 1}: the base has no scheme\n`)
          process.exit(2)
        }

        const ref = parseURI(refStr, i + 1)
        const resolved = resolveURI(base, ref)
        const normalized = normalizeURI(resolved)
        process.stdout.write(normalized + '\n')
      }
    }
  } catch (err) {
    if (err.code) {
      process.exit(err.code)
    }
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }
}

main().catch(err => {
  process.stderr.write((err.message || err) + '\n')
  process.exit(1)
})
"}

