{"file_path":"src/parser.js","content":"/**
 * Parse a URI reference into its components according to RFC 3986.
 */

export function parseURI(str, lineNum) {
  const uri = {
    scheme: null,
    authority: null,
    path: '',
    query: null,
    fragment: null,
    userinfo: null,
    host: null,
    port: null
  }

  let i = 0

  // Parse scheme (optional)
  // Scheme runs to first `:`, but may not be preceded by `/`, `?`, or `#`
  let schemeEnd = -1
  for (let j = 0; j < str.length; j++) {
    if (str[j] === ':') {
      schemeEnd = j
      break
    }
    if (str[j] === '/' || str[j] === '?' || str[j] === '#') {
      // No scheme
      break
    }
  }

  if (schemeEnd !== -1) {
    uri.scheme = str.substring(0, schemeEnd)
    i = schemeEnd + 1
  }

  // Parse authority (optional, introduced by //)
  if (str[i] === '/' && str[i + 1] === '/') {
    i += 2
    let authorityEnd = i
    for (; authorityEnd < str.length; authorityEnd++) {
      if (str[authorityEnd] === '/' || str[authorityEnd] === '?' || str[authorityEnd] === '#') {
        break
      }
    }
    uri.authority = str.substring(i, authorityEnd)
    i = authorityEnd

    // Parse userinfo, host, and port from authority
    parseAuthority(uri, lineNum)
  }

  // Parse path (runs to next ? or #)
  let pathEnd = i
  for (; pathEnd < str.length; pathEnd++) {
    if (str[pathEnd] === '?' || str[pathEnd] === '#') {
      break
    }
  }
  uri.path = str.substring(i, pathEnd)
  i = pathEnd

  // Validate percent-encodings in path
  validatePercentEncodings(uri.path, 'path', lineNum)

  // Parse query (optional, from ? to #)
  if (str[i] === '?') {
    i++
    let queryEnd = i
    for (; queryEnd < str.length; queryEnd++) {
      if (str[queryEnd] === '#') {
        break
      }
    }
    uri.query = str.substring(i, queryEnd)
    i = queryEnd

    // Validate percent-encodings in query
    validatePercentEncodings(uri.query, 'query', lineNum)
  }

  // Parse fragment (optional, from # to end)
  if (str[i] === '#') {
    i++
    uri.fragment = str.substring(i)

    // Validate percent-encodings in fragment
    validatePercentEncodings(uri.fragment, 'fragment', lineNum)
  }

  return uri
}

function parseAuthority(uri, lineNum) {
  const auth = uri.authority

  // userinfo is everything before the last @
  let userinfoEnd = auth.lastIndexOf('@')
  if (userinfoEnd !== -1) {
    uri.userinfo = auth.substring(0, userinfoEnd)
    // Validate percent-encodings in userinfo
    validatePercentEncodings(uri.userinfo, 'userinfo', lineNum)
  }

  // Everything after userinfo (or the whole authority if no userinfo)
  const hostPortStart = userinfoEnd + 1
  const hostPort = auth.substring(hostPortStart)

  // port is everything after the first : that follows the last ]
  let lastBracket = hostPort.lastIndexOf(']')
  let portStart = hostPort.indexOf(':', lastBracket + 1)

  if (portStart !== -1) {
    uri.host = hostPort.substring(0, portStart)
    uri.port = hostPort.substring(portStart + 1)
  } else {
    uri.host = hostPort
  }

  // Validate percent-encodings in host
  validatePercentEncodings(uri.host, 'host', lineNum)
}

function validatePercentEncodings(component, componentName, lineNum) {
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        const err = new Error(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding`)
        err.code = 2
        throw err
      }
      const hex = component.substring(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        const err = new Error(`error: line ${lineNum}: the ${componentName} has a truncated percent-encoding`)
        err.code = 2
        throw err
      }
      i += 2
    }
  }
}
"}

