 * Resolve a URI reference against a base URI according to RFC 3986 section 5.2.2.
 */

export function resolveURI(base, reference) {
  const target = {
    scheme: null,
    authority: null,
    path: '',
    query: null,
    fragment: null
  }

  // If reference has a scheme, it's used as-is (after removing dot segments from path)
  if (reference.scheme) {
    target.scheme = reference.scheme
    target.authority = reference.authority
    target.path = reference.path
    target.query = reference.query
  } else {
    // Use base scheme
    target.scheme = base.scheme

    if (reference.authority) {
      // Reference has authority, use it with base scheme
      target.authority = reference.authority
      target.path = reference.path
      target.query = reference.query
    } else {
      // Reference has no authority, use base authority
      target.authority = base.authority

      if (reference.path === '') {
        // Reference has empty path, use base path
        target.path = base.path

        if (reference.query !== null) {
          target.query = reference.query
        } else {
          target.query = base.query
        }
      } else {
        if (reference.path.startsWith('/')) {
          // Reference path is rooted
          target.path = reference.path
        } else {
          // Merge reference path with base path
          target.path = mergePaths(base, reference.path)
        }
        target.query = reference.query
      }
    }
  }

  target.fragment = reference.fragment

  return target
}

function mergePaths(base, referencePath) {
  if (base.authority && base.path === '') {
    // Base has authority and empty path, return / + reference path
    return '/' + referencePath
  } else {
    // Return everything up to and including last / of base path, plus reference path
    const lastSlash = base.path.lastIndexOf('/')
    if (lastSlash === -1) {
      return referencePath
    } else {
      return base.path.substring(0, lastSlash + 1) + referencePath
    }
  }
}
